    private boolean click(String text){android.view.accessibility.AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(root==null)return false;for(android.view.accessibility.AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(text))if(text.equalsIgnoreCase(String.valueOf(node.getText()))&&node.isEnabled()&&node.isVisibleToUser()){android.graphics.Rect bounds=new android.graphics.Rect();node.getBoundsInScreen(bounds);android.view.accessibility.AccessibilityNodeInfo parent=node;for(int i=0;i<4&&parent!=null;i++,parent=parent.getParent())if(parent.isClickable()&&parent.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK))return true;if(!bounds.isEmpty()){long now=SystemClock.uptimeMillis();test.getUiAutomation().injectInputEvent(android.view.MotionEvent.obtain(now,now,android.view.MotionEvent.ACTION_DOWN,bounds.centerX(),bounds.centerY(),0),true);test.getUiAutomation().injectInputEvent(android.view.MotionEvent.obtain(now,now+80,android.view.MotionEvent.ACTION_UP,bounds.centerX(),bounds.centerY(),0),true);return true;}}return false;}
    private boolean clickDescription(String text){android.view.accessibility.AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(root==null)return false;return description(root,text);}
    private boolean description(android.view.accessibility.AccessibilityNodeInfo node,String text){if(text.equalsIgnoreCase(String.valueOf(node.getContentDescription())))return node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);for(int i=0;i<node.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo child=node.getChild(i);if(child!=null&&description(child,text))return true;}return false;}
